735:<GOTINC>{
                        } /* hex digest */

<WANTDIGEST>[A-Za-z0-9\+/=]+ {
                            /* Only return DIGEST if the length is correct. */
                            yy_size_t len, digest_len =
                                sudo_digest_getlen(digest_type);
                            if (sudoerstext[sudoersleng - 1] == '=') {
                                /* use padding */
                                len = 4 * ((digest_len + 2) / 3);
                            } else {
                                /* no padding */
                                len = (4 * digest_len + 2) / 3;
                            }
                            if ((yy_size_t)sudoersleng == len) {
                                if (!fill(sudoerstext, sudoersleng))
                                    yyterminate();
                                parser_leak_add(LEAK_PTR, sudoerslval.string);
                                BEGIN INITIAL;
                                LEXTRACE("DIGEST ");
                                return DIGEST;
                            }
                            BEGIN INITIAL;
                            sudoersless(sudoersleng);
                        } /* base64 digest */

<INITIAL>@include       {
                            if (continued) {
                                sudoerserror(N_("invalid line continuation"));
                                LEXTRACE("ERROR ");
                                return ERROR;
                            }

                            BEGIN GOTINC;
                            LEXTRACE("INCLUDE ");
                            return INCLUDE;
                        }

<INITIAL>@includedir    {
                            if (continued) {
                                sudoerserror(N_("invalid line continuation"));
                                LEXTRACE("ERROR ");
                                return ERROR;
                            }

                            BEGIN GOTINC;
                            LEXTRACE("INCLUDEDIR ");
                            return INCLUDEDIR;
                        }

<INITIAL>^#include[[:blank:]]+.*(\r\n|\n)? {
                            if (continued) {
                                sudoerserror(N_("invalid line continuation"));
                                LEXTRACE("ERROR ");
                                return ERROR;
                            }

                            /* only consume #include */
                            sudoersless(sizeof("#include") - 1);
                            yy_set_bol(0);

                            BEGIN GOTINC;
                            LEXTRACE("INCLUDE ");
                            return INCLUDE;
                        }

<INITIAL>^#includedir[[:blank:]]+.*(\r\n|\n)? {
                            if (continued) {
                                sudoerserror(N_("invalid line continuation"));
                                LEXTRACE("ERROR ");
                                return ERROR;
                            }

                            /* only consume #includedir */
                            sudoersless(sizeof("#includedir") - 1);
                            yy_set_bol(0);

                            BEGIN GOTINC;
                            LEXTRACE("INCLUDEDIR ");
                            return INCLUDEDIR;
                        }
